  IF expected_kind IS NOT NULL AND NOT EXISTS(SELECT 1 FROM exception_evidence p WHERE p.admission_id = e_id AND p.role = 'DOCTOR' AND p.kind = expected_kind AND JSON_CONTAINS(NEW.evidence_ids, JSON_QUOTE(CAST(p.id AS CHAR)))) THEN
