  DECLARE v_a_id UUID DEFAULT NULL;
  DECLARE v_a_adm UUID DEFAULT NULL;
  DECLARE v_a_stay UUID DEFAULT NULL;
  DECLARE v_a_time DATETIME(6) DEFAULT NULL;
