    SELECT id INTO v_dummy_bed FROM beds WHERE id = NEW.old_bed_id FOR UPDATE;
  END IF;
  IF v_a_id IS NULL OR NOT (v_a_adm <=> v_e_id) OR NOT (v_a_stay <=> v_p_id)
