CREATE TRIGGER append_only_care_billing_events_cols BEFORE UPDATE ON care_billing_events FOR EACH ROW
BEGIN
  -- The dedicated test owner account (absent on the hosting database) may prepare fixtures, as the former table owner could.
  IF USER() NOT LIKE 'hims_test_owner@%' THEN
  IF NOT (NEW.`id` <=> OLD.`id`
    AND NEW.`admission_id` <=> OLD.`admission_id`
    AND NEW.`order_id` <=> OLD.`order_id`
    AND NEW.`round_id` <=> OLD.`round_id`
    AND NEW.`category` <=> OLD.`category`
    AND NEW.`item_id` <=> OLD.`item_id`
    AND NEW.`quantity` <=> OLD.`quantity`
    AND NEW.`unit` <=> OLD.`unit`
    AND NEW.`created_at` <=> OLD.`created_at`) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only tariff_version_id, resolution_reason, state may change on care_billing_events; record a linked correction instead';
  END IF;
  END IF;
END$$
