-- final_reversal_source (charge_reversals BEFORE INSERT; pg final_reversal_source; T1)
DROP TRIGGER IF EXISTS `final_reversal_source`$$
CREATE TRIGGER `final_reversal_source` BEFORE INSERT ON `charge_reversals` FOR EACH ROW
trg: BEGIN
  DECLARE e_id UUID;
  DECLARE e_status VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE e_bill_revision INT;
  DECLARE e_hospital_id UUID;
  DECLARE e_admitting_doctor_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE staff_role VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_admission_id UUID;
  DECLARE a_type VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_disposition VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_bill_version INT;
  DECLARE a_correction_kind VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_source_id UUID;
  DECLARE b_id UUID;
  DECLARE b_category TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE b_item_id TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE b_quantity TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE b_unit TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE b_tariff_version_id UUID;
  DECLARE b_order_id UUID;
  DECLARE b_round_id UUID;
  DECLARE b_created_at DATETIME(6);
  DECLARE policy LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
  DECLARE c_id UUID;
  DECLARE c_admission_id UUID;
  DECLARE c_source_event_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE c_category TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE c_amount_paise BIGINT;
  DECLARE prior BIGINT;
  DECLARE amend_id UUID;
  DECLARE amend_stay_id UUID;
  DECLARE amend_admission_id UUID;
  DECLARE amend_signed_by TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE st_id UUID;
  DECLARE st_amendment_id UUID;
  DECLARE st_started_at DATETIME(6);
  DECLARE st_ended_at DATETIME(6);
  DECLARE st_tariff_version_id UUID;
  DECLARE elapsed DECIMAL(40,6);
  DECLARE unit_ms DECIMAL(40,6);
  DECLARE rate_v DECIMAL(40,6);
  DECLARE due DECIMAL(40,6);
  DECLARE net_v DECIMAL(40,6);
  SELECT id, admission_id, source_event_id, category, amount_paise INTO c_id, c_admission_id, c_source_event_id, c_category, c_amount_paise FROM charges WHERE id = NEW.charge_id;
  SELECT id, status, bill_revision, hospital_id, admitting_doctor_id INTO e_id, e_status, e_bill_revision, e_hospital_id, e_admitting_doctor_id FROM admissions WHERE id = c_admission_id FOR UPDATE;
  SELECT role INTO staff_role FROM staff_user WHERE id = NEW.actor_id AND NOT COALESCE(banned, 0);
  SELECT COALESCE(SUM(amount_paise), 0) INTO prior FROM charge_reversals WHERE charge_id = c_id;
  IF prior + NEW.amount_paise > c_amount_paise THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Reversal exceeds remaining original source';
  END IF;
  IF c_category = 'room' OR c_source_event_id LIKE 'room:%' THEN
    SELECT id, stay_id, admission_id, signed_by INTO amend_id, amend_stay_id, amend_admission_id, amend_signed_by FROM stay_boundary_amendments WHERE id = NEW.physical_amendment_id;
    SELECT id, amendment_id, started_at, ended_at, tariff_version_id INTO st_id, st_amendment_id, st_started_at, st_ended_at, st_tariff_version_id FROM effective_room_stays WHERE id = amend_stay_id LIMIT 1;
    IF NEW.correction_exception_id IS NOT NULL OR NEW.actor_type <> 'staff' OR NOT (staff_role <=> 'ADMIN')
       OR amend_id IS NULL OR NOT (st_amendment_id <=> amend_id) OR NOT (amend_admission_id <=> e_id)
       OR NOT (amend_signed_by <=> NEW.actor_id) OR c_source_event_id NOT LIKE CONCAT('room:', st_id, ':%') THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Room reversal requires the current original-source physical amendment';
    END IF;
    SELECT payload INTO policy FROM setting_versions WHERE id = st_tariff_version_id;
    SET elapsed = GREATEST(0, COALESCE(FLOOR(UNIX_TIMESTAMP(st_ended_at) * 1000) - FLOOR(UNIX_TIMESTAMP(st_started_at) * 1000) - COALESCE(CAST(JSON_VALUE(policy, '$.graceMinutes') AS DECIMAL(30,6)), 0) * 60000, 0));
    SET unit_ms = CASE WHEN JSON_VALUE(policy, '$.basis') = 'hour' THEN 3600000 ELSE 86400000 END;
    SET rate_v = CAST(JSON_VALUE(policy, '$.amount') AS DECIMAL(30,6));
    SET due = CASE WHEN JSON_VALUE(policy, '$.rounding') = 'started-unit' THEN (CAST(FLOOR(elapsed + unit_ms - 1) AS SIGNED) DIV unit_ms) * rate_v ELSE (CAST(FLOOR(elapsed * rate_v + unit_ms / 2) AS SIGNED) DIV unit_ms) END;
    SELECT COALESCE(SUM(ch.amount_paise - COALESCE((SELECT SUM(r.amount_paise) FROM charge_reversals r WHERE r.charge_id = ch.id), 0)), 0) INTO net_v FROM charges ch WHERE ch.admission_id = e_id AND ch.source_event_id LIKE CONCAT('room:', st_id, ':%');
    IF net_v - NEW.amount_paise < due THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Physical correction cannot waive occupied time or double-credit the pinned room rate';
    END IF;
    LEAVE trg;
  END IF;
  IF NEW.physical_amendment_id IS NOT NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Physical amendment only corrects its original room source';
  END IF;
  IF NEW.correction_exception_id IS NOT NULL THEN
    SELECT admission_id, type, disposition, CAST(JSON_VALUE(snapshot, '$.billVersion') AS SIGNED), correction_kind, source_id INTO a_admission_id, a_type, a_disposition, a_bill_version, a_correction_kind, a_source_id FROM admin_exceptions WHERE id = NEW.correction_exception_id;
    IF NOT (e_status <=> 'DISCHARGED') OR NEW.actor_type <> 'staff' OR staff_role IS NULL OR NOT (a_admission_id <=> e_id) OR NOT (a_type <=> 'POST_DISCHARGE_CORRECTION') OR NOT (a_disposition <=> 'AMEND') OR NOT (a_bill_version <=> e_bill_revision) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Closed financial effect needs fresh exact Admin authority';
    END IF;
    IF NOT (a_correction_kind <=> 'REVERSE_CHARGE') OR NOT (a_source_id <=> c_id) OR staff_role NOT IN ('ADMIN','BILLING') THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Closed reversal requires proper Billing role and original non-room charge';
    END IF;
  ELSEIF e_status = 'DISCHARGED' AND c_category <> 'room' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Closed non-room money requires exact source-bound amendment authority';
  END IF;
END$$
-- charge_reversals_immutable_upd (charge_reversals BEFORE UPDATE; pg charge_reversals_immutable; T3)
