-- final_charge_source (charges BEFORE INSERT; pg final_charge_source; T1)
DROP TRIGGER IF EXISTS `final_charge_source`$$
CREATE TRIGGER `final_charge_source` BEFORE INSERT ON `charges` FOR EACH ROW
trg: BEGIN
  DECLARE e_id UUID;
  DECLARE e_status VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE e_bill_revision INT;
  DECLARE e_hospital_id UUID;
  DECLARE e_admitting_doctor_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE staff_role VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_admission_id UUID;
  DECLARE a_type VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_disposition VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_bill_version INT;
  DECLARE a_correction_kind VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_source_id UUID;
  DECLARE b_id UUID;
  DECLARE b_category TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE b_item_id TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE b_quantity TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE b_unit TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE b_tariff_version_id UUID;
  DECLARE b_order_id UUID;
  DECLARE b_round_id UUID;
  DECLARE b_created_at DATETIME(6);
  DECLARE policy LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
  SELECT id, status, bill_revision, hospital_id, admitting_doctor_id INTO e_id, e_status, e_bill_revision, e_hospital_id, e_admitting_doctor_id FROM admissions WHERE id = NEW.admission_id FOR UPDATE;
  SELECT role INTO staff_role FROM staff_user WHERE id = NEW.actor_id AND NOT COALESCE(banned, 0);
  IF NEW.correction_exception_id IS NOT NULL THEN
    SELECT admission_id, type, disposition, CAST(JSON_VALUE(snapshot, '$.billVersion') AS SIGNED), correction_kind, source_id INTO a_admission_id, a_type, a_disposition, a_bill_version, a_correction_kind, a_source_id FROM admin_exceptions WHERE id = NEW.correction_exception_id;
    IF NOT (e_status <=> 'DISCHARGED') OR NEW.actor_type <> 'staff' OR staff_role IS NULL OR NOT (a_admission_id <=> e_id) OR NOT (a_type <=> 'POST_DISCHARGE_CORRECTION') OR NOT (a_disposition <=> 'AMEND') OR NOT (a_bill_version <=> e_bill_revision) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Closed financial effect needs fresh exact Admin authority';
    END IF;
    SELECT id, category, item_id, quantity, unit, tariff_version_id, order_id, round_id, created_at INTO b_id, b_category, b_item_id, b_quantity, b_unit, b_tariff_version_id, b_order_id, b_round_id, b_created_at FROM care_billing_events WHERE CAST(id AS CHAR) = NEW.source_event_id AND admission_id = e_id LIMIT 1;
    IF a_correction_kind = 'CARE_BILLING' THEN
      IF NOT (b_id <=> a_source_id) OR NOT (b_category <=> NEW.category) OR NOT (b_item_id <=> NEW.item_id) OR NOT (b_quantity <=> NEW.quantity) OR NOT (b_unit <=> NEW.unit) OR NOT (b_tariff_version_id <=> NEW.tariff_version_id) OR NEW.initial_status <> 'FINAL'
         OR NOT ((b_category = 'consultation' AND staff_role = 'DOCTOR' AND e_admitting_doctor_id = NEW.actor_id AND EXISTS(SELECT 1 FROM clinical_rounds r WHERE r.id = b_round_id AND r.admission_id = e_id)) OR (b_category = 'consumable' AND staff_role = 'NURSE' AND EXISTS(SELECT 1 FROM nursing_consumables n WHERE n.id = b_id AND n.admission_id = e_id AND n.item_id = b_item_id AND n.quantity = b_quantity AND n.unit = b_unit) AND EXISTS(SELECT 1 FROM nurse_assignments n WHERE n.admission_id = e_id AND n.nurse_id = NEW.actor_id AND NOT EXISTS(SELECT 1 FROM nurse_assignment_revocations r WHERE r.assignment_id = n.id)))) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Closed care fee requires original performed source quantity pin and current proper role';
      END IF;
      IF NOT EXISTS(SELECT 1 FROM (SELECT signed_at FROM departures WHERE admission_id = e_id UNION ALL SELECT signed_at FROM exceptional_departures WHERE admission_id = e_id) d WHERE b_created_at <= d.signed_at) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Closed care pricing cannot create new retrospective clinical work';
      END IF;
    ELSEIF a_correction_kind IN ('LAB_REPORT','LAB_BILLING') THEN
      IF NOT (staff_role <=> 'LAB') OR NOT (b_order_id <=> a_source_id) OR b_category NOT IN ('lab','radiology') OR NOT EXISTS(SELECT 1 FROM lab_processing WHERE order_id = b_order_id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Closed diagnostic fee requires original performed Lab source';
      END IF;
    ELSE
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No authority for this closed charge';
    END IF;
    SELECT payload INTO policy FROM setting_versions WHERE id = NEW.tariff_version_id AND hospital_id = e_hospital_id;
    IF NOT (JSON_VALUE(policy, '$.type') <=> 'billable-item') OR NOT ((JSON_VALUE(policy, '$.code') COLLATE utf8mb4_nopad_bin) <=> NEW.item_id) OR NOT ((JSON_VALUE(policy, '$.category') COLLATE utf8mb4_nopad_bin) <=> NEW.category) OR NOT ((JSON_VALUE(policy, '$.unit') COLLATE utf8mb4_nopad_bin) <=> NEW.unit) OR NOT (NEW.rate_paise <=> CAST(ROUND(CAST(JSON_VALUE(policy, '$.amount') AS DECIMAL(30,6)), 0) AS SIGNED)) OR NOT (NEW.amount_paise <=> CAST(ROUND(CAST(JSON_VALUE(policy, '$.amount') AS DECIMAL(30,6)) * CAST(NEW.quantity AS DECIMAL(30,6)), 0) AS SIGNED)) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Closed charge must retain the exact configured rate and original quantity';
    END IF;
  ELSEIF e_status = 'DISCHARGED' AND NEW.category <> 'room' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Closed non-room money requires exact source-bound amendment authority';
  END IF;
END$$
