-- clearance_instruction_current (clearance_seals BEFORE INSERT; pg clearance_instruction_current; T1)
DROP TRIGGER IF EXISTS `clearance_instruction_current`$$
CREATE TRIGGER `clearance_instruction_current` BEFORE INSERT ON `clearance_seals` FOR EACH ROW
trg: BEGIN
  DECLARE e_id UUID;
  SELECT id INTO e_id FROM admissions WHERE id = NEW.admission_id FOR UPDATE;
  IF NEW.gate = 'DOCTOR' THEN
    IF EXISTS(SELECT 1 FROM exception_evidence p WHERE p.admission_id = e_id AND p.kind = 'RETURN_TO_BED' AND NOT EXISTS(SELECT 1 FROM exception_evidence c WHERE c.kind = 'RETURN_CANCELLED' AND c.source_id = p.id) AND NOT EXISTS(SELECT 1 FROM room_returns r WHERE r.doctor_evidence_id = p.id)) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Current return instruction requires actual return or explicit Doctor reconsideration';
    END IF;
  END IF;
END$$
-- clearance_source_guard (clearance_seals BEFORE INSERT; pg clearance_source_guard; T1)
DROP TRIGGER IF EXISTS `clearance_source_guard`$$
CREATE TRIGGER `clearance_source_guard` BEFORE INSERT ON `clearance_seals` FOR EACH ROW
trg: BEGIN
  DECLARE e_id UUID;
  DECLARE s_id UUID;
  DECLARE s_admission_id UUID;
  DECLARE s_gate VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  SELECT id INTO e_id FROM admissions WHERE id = NEW.admission_id FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM staff_user WHERE id = NEW.signed_by AND role = NEW.role AND COALESCE(banned, 0) = 0) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Current actual seal role required';
  END IF;
  IF NEW.gate <> 'DOCTOR' THEN
    SELECT id, admission_id, gate INTO s_id, s_admission_id, s_gate FROM clearance_seals WHERE id = NEW.predecessor_id;
    IF NOT (s_admission_id <=> e_id) OR NOT (NULLIF(FIELD(s_gate, 'DOCTOR', 'PHARMACY', 'NURSING', 'BILLING'), 0) <=> NULLIF(FIELD(NEW.gate, 'DOCTOR', 'PHARMACY', 'NURSING', 'BILLING'), 0) - 1) OR EXISTS(SELECT 1 FROM clearance_invalidations WHERE seal_id = s_id) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Current same-episode predecessor required';
    END IF;
  END IF;
END$$
-- mvp_legacy_seal (clearance_seals BEFORE INSERT; pg mvp_legacy_seal; T2)
DROP TRIGGER IF EXISTS `mvp_legacy_seal`$$
CREATE TRIGGER `mvp_legacy_seal` BEFORE INSERT ON `clearance_seals` FOR EACH ROW
trg: BEGIN
  DECLARE v_lock VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin DEFAULT NULL;
  DECLARE v_key VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin DEFAULT NULL;
  DECLARE v_e_id UUID DEFAULT NULL;
  DECLARE v_e_wv INT DEFAULT NULL;
  DECLARE v_e_status TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin DEFAULT NULL;
  DECLARE v_e_bill INT DEFAULT NULL;
  DECLARE v_e_admitted DATETIME(6) DEFAULT NULL;
  DECLARE v_e_route TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin DEFAULT NULL;
  DECLARE v_e_bed UUID DEFAULT NULL;
  DECLARE v_e_hosp UUID DEFAULT NULL;
  DECLARE v_e_ver INT DEFAULT NULL;
  DECLARE v_e_patient UUID DEFAULT NULL;
  DECLARE v_st_id UUID DEFAULT NULL;
  DECLARE v_st_adm UUID DEFAULT NULL;
  DECLARE v_st_bed UUID DEFAULT NULL;
  DECLARE v_st_ended DATETIME(6) DEFAULT NULL;
  DECLARE v_st_rec DATETIME(6) DEFAULT NULL;
  DECLARE v_approval UUID DEFAULT NULL;
  DECLARE v_ev_recorded DATETIME(6) DEFAULT NULL;
  DECLARE v_ev_bill INT DEFAULT NULL;
  DECLARE v_ev_payload LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL;
  DECLARE v_v_stay UUID DEFAULT NULL;
  DECLARE v_v_vacated DATETIME(6) DEFAULT NULL;
  SELECT id, workflow_version, status, bill_revision, admitted_at, payment_route, bed_id, hospital_id, `version`, patient_id
    INTO v_e_id, v_e_wv, v_e_status, v_e_bill, v_e_admitted, v_e_route, v_e_bed, v_e_hosp, v_e_ver, v_e_patient
    FROM admissions WHERE id = NEW.admission_id FOR UPDATE;
  IF v_e_wv <> 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Legacy professional seals cannot impersonate external MVP authority'; END IF;
END$$
