-- aa_mvp_legacy_workflow_exception_evidence (exception_evidence BEFORE INSERT; pg aa_mvp_legacy_workflow; T1)
DROP TRIGGER IF EXISTS `aa_mvp_legacy_workflow_exception_evidence`$$
CREATE TRIGGER `aa_mvp_legacy_workflow_exception_evidence` BEFORE INSERT ON `exception_evidence` FOR EACH ROW
trg: BEGIN
  DECLARE l_key VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE episode UUID;
  DECLARE e_id UUID;
  SET episode = NEW.admission_id;

  IF episode IS NOT NULL THEN
    SELECT id INTO e_id FROM admissions WHERE id = episode FOR UPDATE;
    IF EXISTS(SELECT 1 FROM admissions WHERE id = episode AND workflow_version <> 1) THEN
