END$$
-- actual_doctor_exit_chronology (exception_evidence BEFORE INSERT; pg actual_doctor_exit_chronology; T1)
DROP TRIGGER IF EXISTS `actual_doctor_exit_chronology`$$
CREATE TRIGGER `actual_doctor_exit_chronology` BEFORE INSERT ON `exception_evidence` FOR EACH ROW
trg: BEGIN
  DECLARE e_id UUID;
  SELECT id INTO e_id FROM admissions WHERE id = NEW.admission_id FOR UPDATE;
  IF NEW.role = 'DOCTOR' AND NEW.kind IN ('DEATH','EXTERNAL_TRANSFER','AGAINST_ADVICE','PLANNED_EXIT') AND EXISTS(SELECT 1 FROM (SELECT departed_at FROM departures WHERE admission_id = e_id UNION ALL SELECT departed_at FROM exceptional_departures WHERE admission_id = e_id) d WHERE d.departed_at < NEW.actual_at) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Actual professional disposition cannot occur after actual hospital exit';
  END IF;
END$$
-- effective_attendance_guard_exception_evidence (exception_evidence BEFORE INSERT; pg effective_attendance_guard; T1)
DROP TRIGGER IF EXISTS `effective_attendance_guard_exception_evidence`$$
CREATE TRIGGER `effective_attendance_guard_exception_evidence` BEFORE INSERT ON `exception_evidence` FOR EACH ROW
trg: BEGIN
  DECLARE n_id UUID;
  DECLARE n_admission_id UUID;
  DECLARE n_nurse_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE n_started_at DATETIME(6);
  DECLARE e_id UUID;
  DECLARE moment DATETIME(6);
  SELECT id, admission_id, nurse_id, started_at INTO n_id, n_admission_id, n_nurse_id, n_started_at FROM nursing_shifts WHERE id = NEW.shift_id;
  IF n_id IS NULL THEN
    LEAVE trg;
  END IF;
  SELECT id INTO e_id FROM admissions WHERE id = n_admission_id FOR UPDATE;
  SET moment = NEW.actual_at;
  IF NOT (n_admission_id <=> NEW.admission_id) OR NOT (n_nurse_id <=> NEW.signed_by) OR moment < n_started_at OR EXISTS(SELECT 1 FROM effective_shift_ends WHERE shift_id = n_id AND ended_at < moment) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Actual care must fit original Nurse attendance';
  END IF;
  IF moment > UTC_TIMESTAMP(6) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Actual attendance evidence cannot be in future';
  END IF;
END$$
-- exception_evidence_source (exception_evidence BEFORE INSERT; pg exception_evidence_source; T1)
DROP TRIGGER IF EXISTS `exception_evidence_source`$$
CREATE TRIGGER `exception_evidence_source` BEFORE INSERT ON `exception_evidence` FOR EACH ROW
trg: BEGIN
  DECLARE e_id UUID;
  DECLARE e_status VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE e_admitted_at DATETIME(6);
  DECLARE e_admitting_doctor_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE n_id UUID;
  DECLARE n_admission_id UUID;
  DECLARE n_nurse_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE n_started_at DATETIME(6);
  SELECT id, status, admitted_at, admitting_doctor_id INTO e_id, e_status, e_admitted_at, e_admitting_doctor_id FROM admissions WHERE id = NEW.admission_id FOR UPDATE;
  IF (e_status <> 'ADMITTED' AND NOT (e_status = 'DISCHARGED' AND NEW.kind IN ('ROOM_CUTOFF','PROFESSIONAL_REVIEW'))) OR NEW.actual_at < e_admitted_at OR NEW.actual_at > UTC_TIMESTAMP(6) OR NEW.signed_at < NEW.actual_at OR NOT EXISTS(SELECT 1 FROM staff_user WHERE id = NEW.signed_by AND role = NEW.role AND NOT banned) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Current professional evidence with factual episode time required';
  END IF;
  IF NEW.kind = 'PROFESSIONAL_REVIEW' AND NOT EXISTS(SELECT 1 FROM admin_exceptions x JOIN exceptional_departures d ON d.id = x.source_id WHERE x.id = NEW.exception_id AND x.admission_id = e_id AND x.type = 'POST_DISCHARGE_CORRECTION' AND x.disposition = 'AMEND' AND x.correction_kind = 'DISPOSITION_REVIEW' AND x.source_id = NEW.source_id AND d.admission_id = e_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Professional follow-up requires specific retained departure authority';
  END IF;
  IF NEW.kind = 'ROOM_CUTOFF' AND NOT EXISTS(SELECT 1 FROM admin_exceptions x WHERE x.id = NEW.exception_id AND x.admission_id = e_id AND x.type = 'ROOM_CUTOFF_CORRECTION' AND x.disposition = 'AMEND' AND x.source_id = NEW.source_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cutoff witness must bind retained original authority';
  END IF;
  IF NEW.role = 'DOCTOR' AND e_admitting_doctor_id <> NEW.signed_by THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Assigned Doctor evidence required';
  END IF;
  IF NEW.role = 'NURSE' THEN
    SELECT id, admission_id, nurse_id, started_at INTO n_id, n_admission_id, n_nurse_id, n_started_at FROM nursing_shifts WHERE id = NEW.shift_id;
    IF NOT (n_admission_id <=> e_id) OR NOT (n_nurse_id <=> NEW.signed_by) OR NEW.actual_at < n_started_at OR EXISTS(SELECT 1 FROM effective_shift_ends WHERE shift_id = n_id AND ended_at < NEW.actual_at) OR NOT EXISTS(SELECT 1 FROM nurse_assignments a WHERE a.admission_id = e_id AND a.nurse_id = NEW.signed_by AND NOT EXISTS(SELECT 1 FROM nurse_assignment_revocations r WHERE r.assignment_id = a.id)) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Current assigned Nurse and actual attendance required';
    END IF;
  END IF;
  IF NEW.vacated_at IS NOT NULL AND (NEW.vacated_at < e_admitted_at OR NEW.vacated_at > NEW.actual_at) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Physical vacancy must precede hospital exit';
  END IF;
END$$
-- exception_instruction_current (exception_evidence BEFORE INSERT; pg exception_instruction_current; T1)
DROP TRIGGER IF EXISTS `exception_instruction_current`$$
CREATE TRIGGER `exception_instruction_current` BEFORE INSERT ON `exception_evidence` FOR EACH ROW
trg: BEGIN
  DECLARE e_id UUID;
  DECLARE e_status VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE d_id UUID;
  DECLARE d_admission_id UUID;
  DECLARE d_kind TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE d_source_id UUID;
  DECLARE d_signed_at DATETIME(6);
  DECLARE v_id UUID;
  DECLARE v_admission_id UUID;
  DECLARE v_vacated_at DATETIME(6);
  SELECT id, status INTO e_id, e_status FROM admissions WHERE id = NEW.admission_id FOR UPDATE;
  IF NEW.kind NOT IN ('RETURN_TO_BED','RETURN_CANCELLED','RETURN_HANDOVER') THEN
    LEAVE trg;
  END IF;
  IF NEW.kind = 'RETURN_CANCELLED' THEN
    SELECT id, admission_id, kind, source_id, signed_at INTO d_id, d_admission_id, d_kind, d_source_id, d_signed_at FROM exception_evidence WHERE id = NEW.source_id;
    SELECT id, admission_id, vacated_at INTO v_id, v_admission_id, v_vacated_at FROM effective_room_vacations WHERE id = d_source_id LIMIT 1;
    IF NOT (d_admission_id <=> e_id) OR NOT (d_kind <=> 'RETURN_TO_BED') OR NEW.actual_at < d_signed_at OR EXISTS(SELECT 1 FROM room_returns WHERE doctor_evidence_id = d_id) OR EXISTS(SELECT 1 FROM exception_evidence WHERE kind = 'RETURN_CANCELLED' AND source_id = d_id) OR EXISTS(SELECT 1 FROM exception_evidence WHERE admission_id = e_id AND kind = 'RETURN_HANDOVER' AND source_id = d_source_id AND actual_at >= d_signed_at) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Doctor reconsideration requires an unconsumed unwitnessed current return instruction; record actual return first';
    END IF;
  ELSE
    SELECT id, admission_id, vacated_at INTO v_id, v_admission_id, v_vacated_at FROM effective_room_vacations WHERE id = NEW.source_id LIMIT 1;
    SELECT p.id, p.signed_at INTO d_id, d_signed_at FROM exception_evidence p WHERE p.admission_id = e_id AND p.kind = 'RETURN_TO_BED' AND p.source_id = v_id AND NOT EXISTS(SELECT 1 FROM exception_evidence c WHERE c.kind = 'RETURN_CANCELLED' AND c.source_id = p.id) AND NOT EXISTS(SELECT 1 FROM room_returns r WHERE r.doctor_evidence_id = p.id) ORDER BY p.signed_at DESC LIMIT 1;
    IF NEW.kind = 'RETURN_TO_BED' AND d_id IS NOT NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Review existing return instruction before another';
    END IF;
    IF NEW.kind = 'RETURN_HANDOVER' AND (d_id IS NULL OR NEW.actual_at < d_signed_at) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Actual return handover requires current Doctor instruction';
    END IF;
  END IF;
  IF e_status <> 'ADMITTED' OR NOT (v_admission_id <=> e_id) OR NEW.actual_at < v_vacated_at THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Return evidence requires current same-episode factual vacancy';
  END IF;
END$$
-- transfer_witness_authority (exception_evidence BEFORE INSERT; pg transfer_witness_authority; T3)
DROP TRIGGER IF EXISTS `transfer_witness_authority`$$
CREATE TRIGGER `transfer_witness_authority` BEFORE INSERT ON `exception_evidence` FOR EACH ROW
BEGIN
  DECLARE v_e_id UUID DEFAULT NULL;
  DECLARE v_e_status TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin DEFAULT NULL;
  DECLARE v_e_doctor TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin DEFAULT NULL;
  DECLARE v_o_id UUID DEFAULT NULL;
  DECLARE v_o_adm UUID DEFAULT NULL;
  DECLARE v_o_source UUID DEFAULT NULL;
  DECLARE v_o_signed DATETIME(6) DEFAULT NULL;
  SELECT a.id, a.status, a.admitting_doctor_id INTO v_e_id, v_e_status, v_e_doctor FROM admissions a WHERE a.id = NEW.admission_id FOR UPDATE;
  IF NEW.kind = 'TRANSFER_HANDOVER' THEN
    SELECT o.id, o.admission_id, o.source_stay_id, o.signed_at INTO v_o_id, v_o_adm, v_o_source, v_o_signed FROM transfer_orders o WHERE o.id = NEW.source_id;
    IF NOT (v_e_status <=> 'ADMITTED') OR NOT (v_o_adm <=> v_e_id)
       OR NOT (v_o_id <=> (SELECT t.id FROM transfer_orders t WHERE t.admission_id = v_e_id ORDER BY t.version DESC LIMIT 1))
       OR NOT EXISTS(SELECT 1 FROM effective_room_stays s WHERE s.id = v_o_source AND s.admission_id = v_e_id AND s.ended_at IS NULL)
       OR EXISTS(SELECT 1 FROM transfer_order_cancellations c WHERE c.transfer_order_id = v_o_id AND NEW.actual_at >= c.signed_at)
       OR EXISTS(SELECT 1 FROM admission_transfers t WHERE t.transfer_order_id = v_o_id) OR NEW.actual_at < v_o_signed
    THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Witnessed transfer requires current uncancelled original authority';
    END IF;
  END IF;
END$$
