-- append_only_hospital_settings_del (hospital_settings BEFORE DELETE; pg 00_append_only_del; T4)
DROP TRIGGER IF EXISTS append_only_hospital_settings_del$$
CREATE TRIGGER append_only_hospital_settings_del BEFORE DELETE ON hospital_settings FOR EACH ROW
BEGIN
  -- The dedicated test owner account (absent on the hosting database) may prepare fixtures, as the former table owner could.
  IF USER() NOT LIKE 'hims_test_owner@%' THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'hospital_settings records are append-only; record a linked correction instead';
  END IF;
END$$
-- append_only_insurance_cases_del (insurance_cases BEFORE DELETE; pg 00_append_only_del; T4)
DROP TRIGGER IF EXISTS append_only_insurance_cases_del$$
CREATE TRIGGER append_only_insurance_cases_del BEFORE DELETE ON insurance_cases FOR EACH ROW
BEGIN
  -- The dedicated test owner account (absent on the hosting database) may prepare fixtures, as the former table owner could.
  IF USER() NOT LIKE 'hims_test_owner@%' THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'insurance_cases records are append-only; record a linked correction instead';
  END IF;
END$$
-- append_only_insurance_cases_cols (insurance_cases BEFORE UPDATE; pg 00_append_only_cols; T4)
DROP TRIGGER IF EXISTS append_only_insurance_cases_cols$$
CREATE TRIGGER append_only_insurance_cases_cols BEFORE UPDATE ON insurance_cases FOR EACH ROW
BEGIN
  -- The dedicated test owner account (absent on the hosting database) may prepare fixtures, as the former table owner could.
  IF USER() NOT LIKE 'hims_test_owner@%' THEN
  IF NOT (NEW.`id` <=> OLD.`id`
    AND NEW.`admission_id` <=> OLD.`admission_id`
    AND NEW.`recorded_by` <=> OLD.`recorded_by`
    AND NEW.`recorded_at` <=> OLD.`recorded_at`) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only assigned_staff_id, version, review_revision, document_set_revision may change on insurance_cases; record a linked correction instead';
  END IF;
  END IF;
END$$
