-- aa_mvp_legacy_workflow_lab_dispositions (lab_dispositions BEFORE INSERT; pg aa_mvp_legacy_workflow; T1)
DROP TRIGGER IF EXISTS `aa_mvp_legacy_workflow_lab_dispositions`$$
CREATE TRIGGER `aa_mvp_legacy_workflow_lab_dispositions` BEFORE INSERT ON `lab_dispositions` FOR EACH ROW
trg: BEGIN
  DECLARE l_key VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE episode UUID;
  DECLARE e_id UUID;
  SET episode = NEW.admission_id;

  IF episode IS NOT NULL THEN
    SELECT id INTO e_id FROM admissions WHERE id = episode FOR UPDATE;
    IF EXISTS(SELECT 1 FROM admissions WHERE id = episode AND workflow_version <> 1) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Legacy chart, Doctor-login and native department sources require a version 1 episode';
    END IF;
  END IF;
END$$
-- lab_disposition_source (lab_dispositions BEFORE INSERT; pg lab_disposition_source; T1)
DROP TRIGGER IF EXISTS `lab_disposition_source`$$
CREATE TRIGGER `lab_disposition_source` BEFORE INSERT ON `lab_dispositions` FOR EACH ROW
trg: BEGIN
  DECLARE o_id UUID;
  DECLARE o_admission_id UUID;
  DECLARE o_kind TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE e_id UUID;
  DECLARE c_id UUID;
  DECLARE c_initial_status TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE c_amount_paise BIGINT;
  DECLARE r_id UUID;
  DECLARE r_charge_id UUID;
  DECLARE r_amount_paise BIGINT;
  SELECT id, admission_id, kind INTO o_id, o_admission_id, o_kind FROM clinical_orders WHERE id = NEW.order_id;
  SELECT id INTO e_id FROM admissions WHERE id = o_admission_id FOR UPDATE;
  IF o_kind NOT IN ('LAB','RADIOLOGY') OR o_admission_id <> NEW.admission_id OR NOT EXISTS(SELECT 1 FROM clinical_task_events WHERE id = NEW.stop_event_id AND order_id = o_id AND status = 'STOPPED') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Disposition requires actual stopped diagnostic source';
  END IF;
  IF EXISTS(SELECT 1 FROM lab_samples WHERE order_id = o_id) OR EXISTS(SELECT 1 FROM lab_processing WHERE order_id = o_id) OR EXISTS(SELECT 1 FROM lab_reports WHERE order_id = o_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Performed diagnostic work cannot be cancelled as unperformed';
  END IF;
  SELECT ch.id, ch.initial_status, ch.amount_paise INTO c_id, c_initial_status, c_amount_paise FROM charges ch JOIN care_billing_events b ON CAST(b.id AS CHAR) = ch.source_event_id WHERE b.order_id = o_id LIMIT 1;
  IF c_id IS NOT NULL THEN
    IF c_initial_status <> 'PENDING' OR EXISTS(SELECT 1 FROM charge_finalizations WHERE charge_id = c_id) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only original pending source can receive unperformed disposition';
    END IF;
    IF c_amount_paise > 0 THEN
      SELECT id, charge_id, amount_paise INTO r_id, r_charge_id, r_amount_paise FROM charge_reversals WHERE id = NEW.reversal_id;
      IF r_id IS NULL OR r_charge_id <> c_id OR r_amount_paise <> c_amount_paise OR (SELECT COALESCE(SUM(amount_paise), 0) FROM charge_reversals WHERE charge_id = c_id) <> c_amount_paise THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Disposition must reverse the exact original source amount';
      END IF;
    ELSEIF NEW.reversal_id IS NOT NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Zero-price source needs no fake reversal';
    END IF;
  ELSEIF NEW.reversal_id IS NOT NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Disposition cannot reverse a missing source';
  END IF;
END$$
