-- lab_processing_source (lab_processing BEFORE INSERT; pg lab_processing_source; T1)
DROP TRIGGER IF EXISTS `lab_processing_source`$$
CREATE TRIGGER `lab_processing_source` BEFORE INSERT ON `lab_processing` FOR EACH ROW
trg: BEGIN
  DECLARE o_id UUID;
  DECLARE o_admission_id UUID;
  DECLARE o_kind TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE e_patient_id UUID;
  DECLARE s_id UUID;
  DECLARE p_id UUID;
  DECLARE p_sample_id UUID;
  DECLARE e_id UUID;
  SELECT id, admission_id, kind INTO o_id, o_admission_id, o_kind FROM clinical_orders WHERE id = NEW.order_id;
  SELECT id, patient_id INTO e_id, e_patient_id FROM admissions WHERE id = o_admission_id FOR UPDATE;
  IF o_kind NOT IN ('LAB','RADIOLOGY') OR NEW.admission_id <> o_admission_id THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Diagnostic order/episode mismatch';
  END IF;
  SELECT id INTO s_id FROM lab_samples WHERE order_id = o_id LIMIT 1;
  IF (o_kind = 'LAB' AND (s_id IS NULL OR NOT (NEW.sample_id <=> s_id))) OR (o_kind = 'RADIOLOGY' AND NEW.sample_id IS NOT NULL) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Diagnostic sample binding mismatch';
  END IF;
  IF EXISTS(SELECT 1 FROM clinical_task_events WHERE order_id = o_id AND status = 'STOPPED') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Doctor-stopped work cannot begin processing';
  END IF;
  IF EXISTS(SELECT 1 FROM lab_dispositions WHERE order_id = o_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unperformed diagnostic order was disposed';
  END IF;
END$$
