-- effective_attendance_guard_medication_administrations (medication_administrations BEFORE INSERT; pg effective_attendance_guard; T1)
DROP TRIGGER IF EXISTS `effective_attendance_guard_medication_administrations`$$
CREATE TRIGGER `effective_attendance_guard_medication_administrations` BEFORE INSERT ON `medication_administrations` FOR EACH ROW
trg: BEGIN
  DECLARE n_id UUID;
  DECLARE n_admission_id UUID;
  DECLARE n_nurse_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE n_started_at DATETIME(6);
  DECLARE e_id UUID;
  DECLARE moment DATETIME(6);
  SELECT id, admission_id, nurse_id, started_at INTO n_id, n_admission_id, n_nurse_id, n_started_at FROM nursing_shifts WHERE id = NEW.shift_id;
  IF n_id IS NULL THEN
    LEAVE trg;
  END IF;
  SELECT id INTO e_id FROM admissions WHERE id = n_admission_id FOR UPDATE;
  SET moment = NEW.actual_at;
  IF NOT (n_admission_id <=> NEW.admission_id) OR NOT (n_nurse_id <=> NEW.signed_by) OR moment < n_started_at OR EXISTS(SELECT 1 FROM effective_shift_ends WHERE shift_id = n_id AND ended_at < moment) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Actual care must fit original Nurse attendance';
  END IF;
END$$
