  SELECT m.id, 'mvp_transfer_authorities', CAST(NEW.id AS CHAR) FROM mvp_events m WHERE m.admission_id = NEW.admission_id AND m.action IN ('doctor-approval','checklist','check','n-a','finance');
END$$
