trg: BEGIN
  DECLARE l_key VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE episode UUID;
  DECLARE e_id UUID;
  SET episode = NEW.admission_id;

