-- attendance_vacancy_guard__nursing_shift_ends (nursing_shift_ends BEFORE INSERT; pg attendance_vacancy_guard; T3)
DROP TRIGGER IF EXISTS `attendance_vacancy_guard__nursing_shift_ends`$$
CREATE TRIGGER `attendance_vacancy_guard__nursing_shift_ends` BEFORE INSERT ON `nursing_shift_ends` FOR EACH ROW
BEGIN
  DECLARE v_x INT DEFAULT NULL;
  DECLARE v_episode UUID DEFAULT NULL;
  SELECT n.admission_id INTO v_episode FROM nursing_shifts n WHERE n.id = NEW.shift_id;
  SELECT 1 INTO v_x FROM admissions WHERE id = v_episode FOR UPDATE;
  IF EXISTS(SELECT 1 FROM effective_vacation_facts f WHERE f.shift_id = NEW.shift_id AND f.vacated_at > NEW.ended_at) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Shift end cannot precede recorded physical bed vacancy';
  END IF;
END$$
-- effective_attendance_guard_nursing_shift_ends (nursing_shift_ends BEFORE INSERT; pg effective_attendance_guard; T1)
DROP TRIGGER IF EXISTS `effective_attendance_guard_nursing_shift_ends`$$
CREATE TRIGGER `effective_attendance_guard_nursing_shift_ends` BEFORE INSERT ON `nursing_shift_ends` FOR EACH ROW
trg: BEGIN
  DECLARE n_id UUID;
  DECLARE n_admission_id UUID;
  DECLARE n_nurse_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE n_started_at DATETIME(6);
  DECLARE e_id UUID;
  DECLARE moment DATETIME(6);
  SELECT id, admission_id, nurse_id, started_at INTO n_id, n_admission_id, n_nurse_id, n_started_at FROM nursing_shifts WHERE id = NEW.shift_id;
  IF n_id IS NULL THEN
    LEAVE trg;
  END IF;
  SELECT id INTO e_id FROM admissions WHERE id = n_admission_id FOR UPDATE;
  SET moment = NEW.ended_at;
  IF EXISTS(SELECT 1 FROM effective_shift_ends WHERE shift_id = n_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Attendance already has a retained factual end';
  END IF;
  IF NOT (NEW.signed_by <=> n_nurse_id) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only original Nurse signs professional attendance';
    END IF;
  IF EXISTS(SELECT 1 FROM (
      SELECT actual_at AS t FROM medication_administrations WHERE shift_id = n_id
      UNION ALL SELECT observed_at FROM nursing_observations WHERE shift_id = n_id
      UNION ALL SELECT used_at FROM nursing_consumables WHERE shift_id = n_id
      UNION ALL SELECT transferred_at FROM admission_transfers WHERE shift_id = n_id
      UNION ALL SELECT vacated_at FROM effective_vacation_facts WHERE shift_id = n_id
      UNION ALL SELECT actual_at FROM exception_evidence WHERE shift_id = n_id
    ) facts WHERE t > moment) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Attendance cannot end before actual care or physical handover';
  END IF;
  IF moment <= n_started_at OR EXISTS(SELECT 1 FROM departures WHERE admission_id = e_id AND departed_at < moment) OR EXISTS(SELECT 1 FROM exceptional_departures WHERE admission_id = e_id AND departed_at < moment) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Attendance end outside actual episode';
  END IF;
END$$
-- exception_attendance_end (nursing_shift_ends BEFORE INSERT; pg exception_attendance_end; T1)
DROP TRIGGER IF EXISTS `exception_attendance_end`$$
CREATE TRIGGER `exception_attendance_end` BEFORE INSERT ON `nursing_shift_ends` FOR EACH ROW
trg: BEGIN
  DECLARE episode UUID;
  DECLARE e_id UUID;
  SELECT admission_id INTO episode FROM nursing_shifts WHERE id = NEW.shift_id;
  SELECT id INTO e_id FROM admissions WHERE id = episode FOR UPDATE;
  IF EXISTS(SELECT 1 FROM exception_evidence WHERE shift_id = NEW.shift_id AND actual_at > NEW.ended_at) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Attendance cannot end before witnessed physical exception evidence';
  END IF;
END$$
