CREATE TRIGGER append_only_paperwork_runs_cols BEFORE UPDATE ON paperwork_runs FOR EACH ROW
BEGIN
  -- The dedicated test owner account (absent on the hosting database) may prepare fixtures, as the former table owner could.
  IF USER() NOT LIKE 'hims_test_owner@%' THEN
  IF NOT (NEW.`id` <=> OLD.`id`
    AND NEW.`case_id` <=> OLD.`case_id`
    AND NEW.`source` <=> OLD.`source`
    AND NEW.`source_hash` <=> OLD.`source_hash`
    AND NEW.`recorded_by` <=> OLD.`recorded_by`
    AND NEW.`recorded_at` <=> OLD.`recorded_at`) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only status, revision, pending_review_id may change on paperwork_runs; record a linked correction instead';
  END IF;
  END IF;
END$$
-- patient_identification_clearance (patient_identifications AFTER INSERT; pg patient_identification_clearance; T3)
