BEGIN
  -- The dedicated test owner account (absent on the hosting database) may prepare fixtures, as the former table owner could.
  IF USER() NOT LIKE 'hims_test_owner@%' THEN
  IF NOT (NEW.`id` <=> OLD.`id`
    AND NEW.`hospital_id` <=> OLD.`hospital_id`
    AND NEW.`medicine_id` <=> OLD.`medicine_id`
    AND NEW.`catalog_version_id` <=> OLD.`catalog_version_id`
    AND NEW.`batch_no` <=> OLD.`batch_no`
    AND NEW.`expires_on` <=> OLD.`expires_on`
    AND NEW.`unit` <=> OLD.`unit`
    AND NEW.`quantity_scale` <=> OLD.`quantity_scale`
    AND NEW.`barcode` <=> OLD.`barcode`
    AND NEW.`reorder_threshold` <=> OLD.`reorder_threshold`
    AND NEW.`signed_by` <=> OLD.`signed_by`
    AND NEW.`signed_at` <=> OLD.`signed_at`) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only available_quantity may change on pharmacy_batches; record a linked correction instead';
  END IF;
  END IF;
END$$
-- pharmacy_stock_matches_ledger_upd (pharmacy_batches BEFORE UPDATE; pg 50_pharmacy_stock_ledger; T5)
DROP TRIGGER IF EXISTS pharmacy_stock_matches_ledger_upd$$
CREATE TRIGGER pharmacy_stock_matches_ledger_upd BEFORE UPDATE ON pharmacy_batches FOR EACH ROW
BEGIN
  IF NOT (NEW.available_quantity <=> OLD.available_quantity)
     AND NEW.available_quantity <> COALESCE((SELECT SUM(m.quantity) FROM pharmacy_movements m WHERE m.batch_id = NEW.id), 0) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Available stock must equal the append-only movement ledger';
  END IF;
END$$
-- pharmacy_batch_identity_immutable (pharmacy_batches BEFORE UPDATE; pg pharmacy_batch_identity_immutable; T2)
DROP TRIGGER IF EXISTS `pharmacy_batch_identity_immutable`$$
CREATE TRIGGER `pharmacy_batch_identity_immutable` BEFORE UPDATE ON `pharmacy_batches` FOR EACH ROW
trg: BEGIN

  -- every column except available_quantity is immutable
  IF NOT (NEW.id <=> OLD.id) OR NOT (NEW.hospital_id <=> OLD.hospital_id) OR NOT (NEW.medicine_id <=> OLD.medicine_id) OR NOT (NEW.catalog_version_id <=> OLD.catalog_version_id)
     OR NOT (NEW.batch_no <=> OLD.batch_no) OR NOT (NEW.expires_on <=> OLD.expires_on) OR NOT (NEW.unit <=> OLD.unit) OR NOT (NEW.quantity_scale <=> OLD.quantity_scale)
     OR NOT (NEW.barcode <=> OLD.barcode) OR NOT (NEW.reorder_threshold <=> OLD.reorder_threshold) OR NOT (NEW.signed_by <=> OLD.signed_by) OR NOT (NEW.signed_at <=> OLD.signed_at)
  THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Medicine batch identity is immutable; append a new batch or audited movement'; END IF;
END$$
-- pharmacy_movements_clearance (pharmacy_movements AFTER INSERT; pg pharmacy_movements_clearance; T3)
DROP TRIGGER IF EXISTS `pharmacy_movements_clearance`$$
CREATE TRIGGER `pharmacy_movements_clearance` AFTER INSERT ON `pharmacy_movements` FOR EACH ROW
trg: BEGIN
  DECLARE v_ignored TINYINT DEFAULT NULL;
  DECLARE v_episode UUID DEFAULT NULL;
  DECLARE v_category TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin DEFAULT NULL;
  DECLARE v_gate VARCHAR(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin DEFAULT 'PHARMACY';
  SET v_episode = NEW.admission_id;
  IF v_episode IS NULL THEN
    SELECT c.admission_id, c.category INTO v_episode, v_category FROM charges c WHERE c.id = NEW.charge_id;
  END IF;
  IF v_episode IS NULL THEN
    LEAVE trg;
  END IF;
  IF v_category = 'medicine' THEN
    SET v_gate = 'PHARMACY';
  ELSEIF v_category = 'consumable' THEN
    SET v_gate = 'NURSING';
  END IF;
  SET v_ignored = invalidate_clearances(v_episode, v_gate, 'pharmacy_movements', JSON_ARRAY(CAST(NEW.id AS CHAR)));
END$$
